// 파일 책임: 설치한 dialog 복사본을 키트 공통 단위 검사에 연결한다.
import { ConfirmDialog } from '../ui/dialog';
import { checkDialogConformance } from '@boosterlab/web-kit/testing/unit/primitives';
import installation from '../../../../../registry-installation.json';
checkDialogConformance({ ConfirmDialog }, { registryVersion: installation.sourceRef, registryCommit: installation.sourceCommit });

// 파일 책임: 소비 복사본을 키트의 브라우저 검사 화면에 전달한다.
import { createRoot } from 'react-dom/client';
import { createDialogConformancePage } from '@boosterlab/web-kit/testing/fixtures/dialog';
import { Dialog } from '../ui/dialog';
// 프로젝트 테마 CSS(components.json의 tailwind.css = src/styles.css)로 실제 화면과 같은 층·모양에서 검사한다. 위치가 다르면 이 import를 고친다.
import '@/styles.css';
const Page = createDialogConformancePage({ Dialog });
createRoot(document.getElementById('root')!).render(<Page />);

// 파일 책임: 설치한 브라우저 검사 화면을 키트 Playwright 적합성 검사에 연결한다.
import { checkDialogBrowser } from '@boosterlab/web-kit/testing/browser';
import installation from '../../../registry-installation.json' with { type: 'json' };
checkDialogBrowser({ url: '/web-kit-checks/dialog.html', target: { registryVersion: installation.sourceRef, registryCommit: installation.sourceCommit } });
